#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using MVZ2.Metas;
using MVZ2.Modding;
using MVZ2Logic.Almanac;
using PVZEngine;
using UnityEngine;
using static TMPro.SpriteAssetUtilities.TexturePacker_JsonArray;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        public AlmanacMetaList? GetAlmanacMetaList(string nsp)
        {
            var modResource = GetModResource(nsp);
            if (modResource == null)
                return null;
            return modResource.AlmanacMetaList;
        }
        public AlmanacMetaEntry? GetAlmanacMetaEntry(string type, NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            var metaList = GetAlmanacMetaList(id.SpaceName);
            if (metaList == null)
                return null;
            if (!metaList.TryGetCategory(type, out var entries))
                return null;
            if (entries.entries != null)
            {
                foreach (var e in entries.entries)
                {
                    if (e.id == id)
                        return e;
                }
            }
            if (entries.groups != null)
            {
                foreach (var group in entries.groups)
                {
                    foreach (var entry in group.entries)
                    {
                        if (entry.id == id)
                            return entry;
                    }
                }
            }
            return null;
        }
        public AlmanacMetaEntry[] GetAlmanacMetaEntries(string category)
        {
            List<AlmanacMetaEntry> list = new List<AlmanacMetaEntry>();
            foreach (var modResource in modResources)
            {
                var metaList = modResource.AlmanacMetaList;
                if (metaList == null)
                    continue;
                foreach (var categoryMeta in metaList.categories)
                {
                    if (categoryMeta.name != category || categoryMeta.entries == null)
                        continue;
                    list.AddRange(categoryMeta.entries);
                }
            }
            return list.ToArray();
        }
        public AlmanacMetaGroup[] GetAlmanacMetaGroups(string category)
        {
            List<AlmanacMetaGroup> list = new List<AlmanacMetaGroup>();
            foreach (var modResource in modResources)
            {
                var metaList = modResource.AlmanacMetaList;
                if (metaList == null)
                    continue;
                foreach (var categoryMeta in metaList.categories)
                {
                    if (categoryMeta.name != category || categoryMeta.groups == null)
                        continue;
                    list.AddRange(categoryMeta.groups);
                }
            }
            return list.ToArray();
        }
        public AlmanacTagMeta? GetAlmanacTagMeta(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            var metaList = GetAlmanacMetaList(id.SpaceName);
            if (metaList == null)
                return null;
            foreach (var m in metaList.tags)
            {
                if (m.id == id.Path)
                    return m;
            }
            return null;
        }
        public AlmanacVariable? GetAlmanacGlobalVariable(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            var metaList = GetAlmanacMetaList(id.SpaceName);
            if (metaList == null)
                return null;
            foreach (var m in metaList.globalVariables)
            {
                if (m.name == id.Path)
                    return m;
            }
            return null;
        }
        public AlmanacTagEnumMeta? GetAlmanacTagEnumMeta(NamespaceID? id)
        {
            if (!NamespaceID.IsValid(id))
                return null;
            var metaList = GetAlmanacMetaList(id.SpaceName);
            if (metaList == null)
                return null;
            foreach (var m in metaList.enums)
            {
                if (m.id == id.Path)
                    return m;
            }
            return null;
        }
        public IEnumerable<AlmanacTagMeta> GetAllAlmanacTagMetas()
        {
            foreach (var modResource in modResources)
            {
                var metaList = modResource.AlmanacMetaList;
                if (metaList == null)
                    continue;
                foreach (var tag in metaList.tags)
                {
                    yield return tag;
                }
            }
        }
        public IEnumerable<AlmanacTagEnumMeta> GetAllAlmanacTagEnumMetas()
        {
            foreach (var modResource in modResources)
            {
                var metaList = modResource.AlmanacMetaList;
                if (metaList == null)
                    continue;
                foreach (var tagEnum in metaList.enums)
                {
                    yield return tagEnum;
                }
            }
        }
        public bool IsContraptionInAlmanac(NamespaceID id)
        {
            var entry = GetAlmanacMetaEntry(LogicAlmanacCategories.CONTRAPTIONS, id);
            return entry != null && entry.index >= 0;
        }
        public bool IsEnemyInAlmanac(NamespaceID id)
        {
            var entry = GetAlmanacMetaEntry(LogicAlmanacCategories.ENEMIES, id);
            return entry != null && entry.index >= 0;
        }
        private void LoadUnlocks_Almanac(ModResource resource)
        {
            if (resource.AlmanacMetaList == null)
                return;
            foreach (var category in resource.AlmanacMetaList.categories)
            {
                if (category.entries != null)
                {
                    foreach (var entry in category.entries)
                    {
                        AddConditionListUnlocks(entry.unlock);
                        AddConditionListUnlocks(entry.encounterUnlock);
                        AddConditionListUnlocks(entry.silhouetteUnlock);
                    }
                }
                if (category.groups != null)
                {
                    foreach (var group in category.groups)
                    {
                        foreach (var entry in group.entries)
                        {
                            AddConditionListUnlocks(entry.unlock);
                            AddConditionListUnlocks(entry.encounterUnlock);
                            AddConditionListUnlocks(entry.silhouetteUnlock);
                        }
                    }
                }
            }
        }
    }
}
